fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();

    let t: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..t {
        let nm: Vec<usize> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let n = nm[0];
        let m = nm[1].min(n);

        let mut da: Vec<char> = vec!['0'; n + 2];
        let line: String = lines.next().unwrap().chars().take(n).collect();
        for (i, c) in line.chars().enumerate() {
            da[i + 1] = c;
        }

        let mut dup = da.clone();
        for _ in 0..m {
            dup.clone_from_slice(&da);
            for j in 1..=n {
                if da[j] == '0' {
                    let c = dup[j - 1] == '1';
                    let d = dup[j + 1] == '1';
                    if c ^ d {
                        da[j] = '1';
                    }
                }
            }
        }

        for c in da.iter().skip(1).take(n) {
            print!("{}", c);
        }
        println!();
    }
}

