fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<i32> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0] as usize;
    let k = first_line[1];

    let mut a = Vec::with_capacity(n);
    for _ in 0..n {
        let line: Vec<i32> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let f = line[0];
        let t = line[1];
        if t > k {
            a.push(f - (t - k));
        } else {
            a.push(f);
        }
    }

    let mut m = 0;
    let mut p = false;
    let mut q = -1_000_000_000;
    let mut w = false;

    for &value in &a {
        if value > m && value > 0 {
            m = value;
            p = true;
        }
        if value >= q && value < 0 {
            q = value;
            w = true;
        }
    }

    if p && !w {
        println!("{}", m);
    } else if w && !p {
        println!("{}", q);
    } else {
        if (-q) > m {
            println!("{}", q);
        } else {
            println!("{}", m);
        }
    }
}

