        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0];
    let p1 = first_line[1];
    let p2 = first_line[2];
    let p3 = first_line[3];
    let t1 = first_line[4];
    let t2 = first_line[5];

    let mut second_line: Vec<i32> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
