    let mut r = Vec::with_capacity(t);
    let mut a = Vec::with_capacity(t);

    for _ in 0..t {
        let line = match lines.next().and_then(|line| line.ok()) {
            Some(line) => line,
            None => return,
        };
        let mut parts = line.split_whitespace();
        let l_i: i32 = match parts.next().and_then(|s| s.parse().ok()) {
            Some(l_i) if (1..=1_000_000_000).contains(&l_i) => l_i,
            _ => return,
        };
        let r_i: i32 = match parts.next().and_then(|s| s.parse().ok()) {
