    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0];
    let m = first_line[1];

    let mut f = vec![0; n];
    let mut a = vec![0; m];

    for (i, line) in lines.by_ref().take(n).enumerate() {
        let x: usize = line.parse().unwrap();
        if f[x - 1] < n + 1 && f[x - 1] > 0 {
            f[x - 1] = n + 2;
        } else if f[x - 1] == 0 {
            f[x - 1] = i + 1;
        }
    }

