            if n % i == 0 {
                let op = n / i;
                if op <= k && (max.is_none() || op > max.unwrap()) {
                    max = Some(op);
                } else if max.is_none() || i > max.unwrap() {
                    max = Some(i);
                }
            }
        }

        let result = if k >= n {
            1
        } else if max.is_none() {
            n
        } else {
            n / max.unwrap()
        };

