use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut tt = input.trim().parse::<i32>().unwrap();

    while tt > 0 {
        input.clear();
        io::stdin().read_line(&mut input)?;
        let mut parts = input.trim().split_whitespace();
        let a = parts.next().unwrap().parse::<i32>().unwrap();
        let b = parts.next().unwrap().parse::<i32>().unwrap();

        let mut output = String::new();
        if a > b {
            output.extend(std::iter::repeat("01").take(b as usize));
            output.extend(std::iter::repeat("0").take((a - b) as usize));
        } else {
            output.extend(std::iter::repeat("10").take(a as usize));
            output.extend(std::iter::repeat("1").take((b - a) as usize));
        }
        output.push('\n');

        io::stdout().write_all(output.as_bytes())?;
        tt -= 1;
    }

    Ok(())
}

