    {
        f[i + N] = (f[i-1+N] + f[i-k+N]) % MOD;
    }
    for (int i = N-1; i >= 0; i--)
    {
        f[i] = (f[2 * i + 1] + f[2 * i + 2]) % MOD;
    }
