			if (h < ii[j])
				h = ii[j];
			dp[i][j] = (dq[i - 1][j] - (h <= 0 ? 0 : dq[h - 1][j]) + MD) % MD;
			if (a != -1 && j != a)
				dp[i][j] = 0;
			sum = (sum + dp[i][j]) % MD;
		}
		for (j = 1; j <= k; j++)
			dq[i][j] = (dq[i - 1][j] + sum - dp[i][j] + MD) % MD;
		if (a != -1)
			for (j = 1; j <= k; j++)
				if (j != a)
					ii[j] = i;
	}
