        let mut k = m - n - 1;
        for _ in 0..n {
            if k > 0 {
                output.push_str("110");
                k -= 1;
            } else {
                output.push_str("10");
            }
        }
        if k > 0 {
            output.push_str("11");
        } else {
            output.push('1');
        }
    }

    print!("{}", output);
    io::stdout().flush()?;
    Ok(())
}

