            }
            for j in ((k - i - 1)..n).step_by(k) {
                table[s[j] as usize] += 1;
            }
            let max = table.iter().enumerate().max_by_key(|&(_, &v)| v).unwrap().0;
            ans += n / k * 2 - table[max];
        }

        if k % 2 != 0 {
