fn parse_three_integers(s: &str) -> Result<(i32, i32, i32), std::num::ParseIntError> {
    let mut parts = s.split_whitespace();
    let a = parts.next().unwrap_or("").parse()?;
    let b = parts.next().unwrap_or("").parse()?;
    let c = parts.next().unwrap_or("").parse()?;
    Ok((a, b, c))
}

