    if m > (n + 1) * 2 || n > m + 1 {
        output.push_str("-1");
    } else if n == m + 1 {
        output.push('0');
        output.extend(std::iter::repeat("10").take(m as usize));
    } else if m == (n + 1) * 2 {
        output.extend(std::iter::repeat("110").take(n as usize));
        output.push_str("11");
    } else if m == 2 * n + 1 {
        output.extend(std::iter::repeat("110").take(n as usize));
        output.push('1');
    } else {
        let mut m = m;
        let mut n = n;
        while m != 2 * n {
            output.push_str("10");
            if n <= 0 {
                break;
            }
            m -= 1;
            n -= 1;
        }
        output.extend(std::iter::repeat("110").take(n as usize));
    }

    print!("{}", output);
    io::stdout().flush()?;
    Ok(())
}

