            println!("-1");
            continue;
        } else if s > (k - 1) * n + k * b {
            println!("-1");
            continue;
        } else {
            let mut remaining = s;
            let first = if s - k * b - k + 1 >= 0 { k * b + k - 1 } else { s };
            remaining -= first;
            print!("{} ", first);

            for _ in 0..n - 1 {
                if remaining - k + 1 >= 0 {
                    print!("{} ", k - 1);
                    remaining -= k - 1;
                } else if remaining > 0 {
                    print!("{} ", remaining);
                    remaining = 0;
                } else {
                    print!("0 ");
                }
            }
            println!();
        }
    }
