use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;

    let parts: Vec<&str> = input.trim().split_whitespace().collect();
    if parts.len() != 2 {
        writeln!(io::stderr(), "Expected two strings")?;
        return Ok(());
    }

    let ar = parts[0];
    let br = parts[1];

    let c = ar.len();
    let s = br.len();

    match c.cmp(&s) {
        std::cmp::Ordering::Less => writeln!(io::stdout(), "{}", s)?,
        std::cmp::Ordering::Greater => writeln!(io::stdout(), "{}", c)?,
        std::cmp::Ordering::Equal => {
            if ar == br {
                writeln!(io::stdout(), "-1")?;
            } else {
                writeln!(io::stdout(), "{}", c)?;
            }
        }
    }

