                break;
            }
        }
    }

    if f == 0 {
        if m < n - 1 {
            f = 1;
        } else if p.is_none() {
            if m != n {
                f = -1;
            }
        } else {
            let p = p.unwrap();
            for (ai, bi) in a[p + 1..].iter().rev().zip(b[m - (n - p - 1)..].iter().rev()) {
                if ai != bi {
                    f = 1;
                    break;
                }
            }
        }
    }

    if f == 0 {
        println!("YES");
    } else {
        println!("NO");
    }
}

