        let (p, a, b, c) = (parts[0], parts[1], parts[2], parts[3]);

        let a1 = if p % a != 0 {
            (p / a + 1) * a - p
        } else {
            p / a * a - p
        };

        let b1 = if p % b != 0 {
            (p / b + 1) * b - p
        } else {
            p / b * b - p
        };

        let c1 = if p % c != 0 {
            (p / c + 1) * c - p
        } else {
            p / c * c - p
        };

        let min = a1.min(b1).min(c1);
        println!("{}", min);
    }
}

