fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    if let Some(Ok(t_str)) = lines.next() {
        let t: i32 = t_str.parse().unwrap();
        for _ in 0..t {
            if let Some(Ok(line)) = lines.next() {
                let parts: Vec<i32> = line.split_whitespace()
                    .map(|s| s.parse().unwrap())
                    .collect();
                let n = parts[0];
                let a = parts[1];
                let b = parts[2];
                let c = parts[3];
                let d = parts[4];
                let x = n * (a - b);
                let y = n * (a + b);
                match (y.cmp(&(c - d)), y.cmp(&(c + d)), x.cmp(&(c + d))) {
                    (std::cmp::Ordering::Less, _, _) => println!("NO"),
                    (std::cmp::Ordering::Equal, _, _) => println!("YES"),
                    (_, std::cmp::Ordering::Less | std::cmp::Ordering::Equal, _) => println!("YES"),
                    (_, _, std::cmp::Ordering::Greater) => println!("NO"),
                    _ => println!("YES"),
                }
            }
        }
    }
}

