fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut iter = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());

    let x1 = iter.next().unwrap();
    let y1 = iter.next().unwrap();
    let x2 = iter.next().unwrap();
    let y2 = iter.next().unwrap();

    let output = if x1 != x2 && y1 != y2 && (x1 - x2).abs() != (y1 - y2).abs() {
        "-1".to_string()
    } else if x1 == x2 {
        let len = (y2 - y1).abs();
        format!("{} {} {} {}", x1 + len, y1, x2 + len, y2)
    } else if y1 == y2 {
        let len = (x2 - x1).abs();
        format!("{} {} {} {}", x1, y1 + len, x2, y2 + len)
    } else {
        format!("{} {} {} {}", x1, y2, x2, y1)
    };

    io::stdout().write_all(output.as_bytes())?;
    Ok(())
}

