fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut t: i32 = lines.next().unwrap().parse().unwrap();
    let mut table = [0; 26];

    while t > 0 {
        let nk: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let n = nk[0] as usize;
        let k = nk[1] as usize;
        let mut s = Vec::new();
        let mut chars = lines.next().unwrap().chars().filter(|&c| c.is_ascii_lowercase());

        for _ in 0..n {
            s.push(chars.next().unwrap() as u8 - b'a');
        }

        let mut ans = 0;
        for i in 0..k / 2 {
            table.fill(0);
            for j in (i..n).step_by(k) {
                table[s[j] as usize] += 1;
            }
            for j in ((k - i - 1)..n).step_by(k) {
                table[s[j] as usize] += 1;
            }
            let max = table.iter().enumerate().max_by_key(|&(_, &v)| v).unwrap().0;
            ans += n / k * 2 - table[max];
        }

        if k % 2 != 0 {
            table.fill(0);
            for j in (k / 2..n).step_by(k) {
                table[s[j] as usize] += 1;
            }
            let max = table.iter().enumerate().max_by_key(|&(_, &v)| v).unwrap().0;
            ans += n / k - table[max];
        }

        println!("{}", ans);
        t -= 1;
    }
}

