    ans2=0;
    for(i=0;i<n;i++)
    {
        if(!vis[i])
        {
            if(!vis[(i+1)%n])ans2+=(long long)c[i]*c[(i+1)%n];
            if(!vis[(i-1+n)%n])ans2+=(long long)c[i]*c[(i-1+n)%n];
        }
    }
    printf("%I64d\n",(ans2+ans3)/2+ans1);

    return 0;
