use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut first_line = lines.next().unwrap().split_whitespace();
    let n: usize = first_line.next().unwrap().parse().unwrap();
    let k: usize = first_line.next().unwrap().parse().unwrap();

    let mut c: Vec<i32> = Vec::with_capacity(n);
    let mut sum: i64 = 0;
    for value in lines.next().unwrap().split_whitespace().take(n) {
        let num: i32 = value.parse().unwrap();
        c.push(num);
        sum += num as i64;
    }

    let mut vis: Vec<bool> = vec![false; n];
    let mut sum_spe: i64 = 0;
    for _ in 0..k {
        let x: usize = lines.next().unwrap().parse().unwrap();
        vis[x - 1] = true;
        sum_spe += c[x - 1] as i64;
    }

    let ans1 = (sum - sum_spe) * sum_spe;
    let mut ans3: i64 = 0;
    for i in 0..n {
        if vis[i] {
            ans3 += (sum_spe - c[i] as i64) * c[i] as i64;
        }
    }

    let mut ans2: i64 = 0;
    for i in 0..n {
        if !vis[i] {
            if !vis[(i + 1) % n] {
                ans2 += c[i] as i64 * c[(i + 1) % n] as i64;
            }
            if !vis[(i + n - 1) % n] {
                ans2 += c[i] as i64 * c[(i + n - 1) % n] as i64;
            }
        }
    }

    println!("{}", (ans2 + ans3) / 2 + ans1);
}

