        }
        for(i=1 ; i<=n ; i++)
        {
            if(r[i]-l[i]==0)
                continue;
            min=cnt[l[i]];
            d[l[i]][r[i]]=l[i];
            for(j=l[i]+1 ; j<=r[i] ; j++)
            {
