            if m > n {
                output.push('1');
                m -= 1;
            }
        }

        for _ in 0..n - 1 {
            output.push('0');

            if m > n - output.len() as i32 / 2 - 1 {
                output.push_str("11");
                m -= 2;
            } else {
                output.push('1');
                m -= 1;
            }
        }

        output.push('0');

        if m == 1 {
            output.push('1');
        } else if m == 2 {
            output.push_str("11");
        }

        print!("{}", output);
    }

    io::stdout().flush()?;
    Ok(())
}

