        output.push(k);
        output.push(k * 2);
        output.push(k * 3);
    } else {
        let start = k - n / 2 + 1;
        output.push(start);
        output.push(start * 2);
        let mut tmp = 1_000_000_000;
        for i in (1..=n - 2 - (n % 2)).step_by(2) {
            if i == start || i == start + 1 || i == start * 2 || i == start * 2 - 1 {
                output.push(tmp);
