        max_x = max(max_x, xi);
        min_y = min(min_y, yi);
        max_y = max(max_y, yi);
    }

    let x1 = max_x as i64 - min_x as i64;
    let y1 = max_y as i64 - min_y as i64;
    let a = if x1 > y1 { x1 * x1 } else { y1 * y1 };

