        writeln!(io::stdout(), "NO")?;
        return Ok(());
    }

    let (string1, string2) = (parts[0], parts[1]);
    if string1.len() != string2.len() {
        writeln!(io::stdout(), "NO")?;
        return Ok(());
    }

    let mut count1 = [0; 26];
    let mut count2 = [0; 26];
