    for a_i in &mut a {
        let mut count = 0;
        if gap > *a_i {
            gap -= *a_i;
        } else {
            *a_i -= gap;
            if gap != 0 {
                count += 1;
            }
            count += *a_i / m;
            if *a_i % m == 0 {
                gap = 0;
            } else {
                gap = m - (*a_i % m);
