        let b = b - p % b;
        let c = c - p % c;

        let result = match (a, b, c) {
            (a, b, c) if a >= b && b >= c => c,
            (a, b, c) if a >= c && c >= b => b,
            (a, b, c) if b >= c && c >= a => a,
            (a, b, c) if b >= a && a >= c => c,
            (a, b, c) if c >= a && a >= b => b,
            (a, b, c) if c >= b && b >= a => a,
            _ => unreachable!(),
        };

        println!("{}", result);
    }
