        for i in (1..=n).rev() {
            if i == a as usize || i == b as usize {
                continue;
            }
            c[ans] = i as i32;
            ans += 1;
        }

        let mut min = 999999;
        for i in 1..=n / 2 {
            if c[i] < min {
                min = c[i];
            }
        }

        let mut max = 0;
        for i in n / 2 + 1..=n {
            if c[i] > max {
