    scanf("%d %d", &n, &m);
    for (i = 0; i < n; i++)
        scanf("%s", feature[i]);
    for (i = 0; i < n; i++)
        for (j = 0; j < m; j++)
            feature[i][j] = feature[i][j] == 'B' ? -1 : 1;

    ans = 0;
    for (i = n - 1; i >= 0; i--)
        for (j = m - 1; j >= 0; j--) {
            int d = feature[i][j] - field[i][j];
            ans += !!d;
            for (k = 0; k <= i; k++)
