        for (j, c) in line.chars().enumerate() {
            feature[i][j] = if c == 'B' { -1 } else { 1 };
        }
    }

    let mut field = vec![vec![0; m]; n];
    let mut ans = 0;

    for i in (0..n).rev() {
        for j in (0..m).rev() {
            let d = feature[i][j] - field[i][j];
            if d != 0 {
                ans += 1;
                for k in 0..=i {
                    for l in 0..=j {
                        field[k][l] += d;
                    }
                }
            }
        }
    }

    println!("{}", ans);
}

