    let mut adj2 = vec![vec![0; n]; n];

    for i in 0..n {
        for j in 0..n {
            adj1[i][j] = if i == j { 0 } else { INF };
            adj2[i][j] = if i == j { 0 } else { 1 };
        }
    }

