        adj1[v - 1][u - 1] = 1;
        adj2[u - 1][v - 1] = INF;
        adj2[v - 1][u - 1] = INF;
    }

    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                adj1[i][j] = min(adj1[i][j], adj1[i][k] + adj1[k][j]);
            }
        }
