    io::stdin().read_line(&mut input)?;
    let mut tt = input.trim().parse::<i32>().unwrap();

    while tt > 0 {
        input.clear();
        io::stdin().read_line(&mut input)?;
        let mut parts = input.trim().split_whitespace();
        let a = parts.next().unwrap().parse::<i32>().unwrap();
        let b = parts.next().unwrap().parse::<i32>().unwrap();

        let min_ab = a.min(b);
        let abs_diff = (a - b).abs();

        let mut output = String::with_capacity((min_ab * 2 + abs_diff) as usize);
        for _ in 0..min_ab {
            output.push_str("01");
        }
        for _ in 0..abs_diff {
            if a < b {
                output.push('1');
            } else {
                output.push('0');
            }
        }
        output.push('\n');

        io::stdout().write_all(output.as_bytes())?;
        tt -= 1;
    }

    Ok(())
}

