    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let a: i32 = parts.next().unwrap().parse().unwrap();
    let b: i32 = parts.next().unwrap().parse().unwrap();
    let s: Vec<char> = parts.next().unwrap().chars().collect();

    let mut dp = vec![0; n + 1];
    let mut lcp = vec![vec![0; n + 1]; n + 1];
    let mut ll = vec![0; n];

    for i in (0..n).rev() {
        for j in (0..n).rev() {
            lcp[i][j] = if s[i] == s[j] { 1 + lcp[i + 1][j + 1] } else { 0 };
        }
    }

    for j in 0..n {
        for i in 0..j {
            let l = if j - i < lcp[i][j] { j - i } else { lcp[i][j] };
            if ll[j] < l {
                ll[j] = l;
            }
        }
    }

    for i in 0..=n {
        dp[i] = (i as i32) * a;
    }

    for i in 0..n {
        if dp[i + 1] > dp[i] + a {
            dp[i + 1] = dp[i] + a;
        }
        for j in i + 1..=n.min(i + ll[i]) {
            if dp[j] > dp[i] + b {
                dp[j] = dp[i] + b;
            }
        }
    }

    println!("{}", dp[n]);
}

