    let mut first_line = lines.next().unwrap().split_whitespace();
    let n: usize = first_line.next().unwrap().parse().unwrap();
    let m: usize = first_line.next().unwrap().parse().unwrap();
    let b: usize = first_line.next().unwrap().parse().unwrap();
    let mod_val: i32 = first_line.next().unwrap().parse().unwrap();

    let a: Vec<i32> = lines.next().unwrap()
        .split_whitespace()
        .take(n)
        .map(|x| x.parse().unwrap())
        .collect();

    let mut dp = vec![vec![vec![0; b + 1]; m + 1]; 2];
    dp[1][0][0] = 1;

    for i in 0..n {
        let it = i & 1;
        for j in 0..=m {
            for k in 0..=b {
                dp[it][j][k] = dp[it ^ 1][j][k];
                if j >= 1 && k >= a[i] as usize {
                    dp[it][j][k] += dp[it][j - 1][k - a[i] as usize];
                    if dp[it][j][k] >= mod_val {
                        dp[it][j][k] -= mod_val;
                    }
                }
            }
        }
    }

    let ans: i32 = dp[(n - 1) & 1][m].iter().sum::<i32>() % mod_val;
