        if a[i] >= k {
            for j in 0..n {
                if b[i][j] >= 0 {
                    sum += c[a[i] - 1][k - 1] * b[i][j] as f64;
                }
            }
        }
    }

    let result = (sum / c[n][k] + 1e-8).round() as i64;
    println!("{}", result);
}

