fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let (n, m, q) = (first_line[0], first_line[1], first_line[2]);

    let mut a = vec![vec![0; m + 1]; n + 1];
    let mut rows = vec![0; n + 1];

    for i in 1..=n {
        let row: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let mut count = 0;
        let mut max = 0;
        for j in 1..=m {
            a[i][j] = row[j - 1];
            if a[i][j] == 1 {
                count += 1;
            } else {
                count = 0;
            }
            if count > max {
                max = count;
            }
        }
        rows[i] = max;
    }

    for _ in 0..q {
        let query: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let (x1, x2) = (query[0], query[1]);

        a[x1][x2] = if a[x1][x2] == 0 { 1 } else { 0 };

        let mut max1 = 0;
        let mut c = 0;
        for j in 1..=m {
            if a[x1][j] == 1 {
                c += 1;
            } else {
                c = 0;
            }
            if c > max1 {
                max1 = c;
            }
        }
