fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let mut lines = input.lines();
    let first_line = lines.next().unwrap();
    let mut dimensions = first_line.split_whitespace();
    let n: usize = dimensions.next().unwrap().parse().unwrap();
    let m: usize = dimensions.next().unwrap().parse().unwrap();

    let mut grid = vec![vec![' '; m + 2]; n + 2];
    let mut count = 0;
    let mut flag = false;
    let mut top = 0;
    let mut bottom = 0;
    let mut left = 0;
    let mut right = 0;

    for (i, line) in lines.enumerate().take(n) {
        let chars: Vec<char> = line.chars().collect();
        for (j, &c) in chars.iter().enumerate().take(m) {
            grid[i + 1][j + 1] = c;
            if c == 'B' {
                count += 1;
                if !flag {
                    top = i + 1;
                    bottom = i + 1;
                    left = j + 1;
                    right = j + 1;
                    flag = true;
                }
                if j + 1 < left {
                    left = j + 1;
                }
                if j + 1 > right {
                    right = j + 1;
                }
                if i + 1 < top {
                    top = i + 1;
                }
                if i + 1 > bottom {
                    bottom = i + 1;
                }
            }
        }
    }

    if !flag {
        println!("1");
        return Ok(());
    }

    let n1 = bottom - top + 1;
    let n2 = right - left + 1;
    let max = n1.max(n2);

    if max == n1 {
        if max <= m {
            println!("{}", max * max - count);
        } else {
            println!("-1");
        }
    } else {
        if max <= n {
            println!("{}", max * max - count);
        } else {
            println!("-1");
        }
    }

    Ok(())
}

