fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut parts = input.trim().split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let k: usize = parts.next().unwrap().parse().unwrap();

    if k > n {
        writeln!(io::stdout(), "-1")?;
        return Ok(());
    }
    if k == 1 && n > 1 {
        writeln!(io::stdout(), "-1")?;
        return Ok(());
    }
    if n == 1 {
        writeln!(io::stdout(), "a")?;
        return Ok(());
    }
    if n == 2 {
        writeln!(io::stdout(), "ab")?;
        return Ok(());
    }

    let mut a = vec![0; n];
    let k = k - 2;
    let j = n - k;

    for (i, item) in a.iter_mut().take(j).enumerate() {
        *item = if i % 2 == 0 { b'a' } else { b'b' };
    }

    for (l, item) in a.iter_mut().skip(j).take(k).enumerate() {
        *item = (99 + l) as u8;
    }

    writeln!(io::stdout(), "{}", String::from_utf8_lossy(&a))?;
    Ok(())
}

