			if (a != -1 && j != a)
				dp[i][j] = 0;
			sum = (sum + dp[i][j]) % MD;
		}
		for (j = 1; j <= k; j++)
			dq[i][j] = (dq[i - 1][j] + sum - dp[i][j] + MD) % MD;
