        }
    }

    dp[0][0] = 1;
    for i in 1..MAXN {
        for j in 0..MAXM {
            for k in (i..=j).step_by(i) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD;
            }
        }
    }

    fac[0] = 1;
    for i in 1..MAXN {
