    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let (n, m) = (first_line[0], first_line[1]);

    let mut translations = Vec::with_capacity(m);
    for _ in 0..m {
        let line: Vec<String> = lines.next().unwrap().split_whitespace()
            .map(String::from)
            .collect();
        translations.push((line[0].clone(), line[1].clone()));
    }

    for _ in 0..n {
        let word = lines.next().unwrap();
        let mut translated = false;
        for (from, to) in &translations {
            if word == *from || word == *to {
                let chosen = match from.len().cmp(&to.len()) {
                    Ordering::Less => from,
                    Ordering::Greater => to,
                    Ordering::Equal => from,
                };
                print!("{} ", chosen);
                translated = true;
                break;
            }
        }
        if !translated {
            print!("{} ", word);
        }
    }
    println!();
}

