                    if let Ok((a, b, c)) = parse_three_integers(&line) {
                        let sum_mod_3 = (a + b + c) % 3;
                        let result = if sum_mod_3 == 2 { 1 } else { sum_mod_3 };
                        println!("{}", result);
                    }
                }
