        return Ok(());
    }

    let mut n = n / 2;
    let mut output = String::new();
    for (a, b) in s.chars().zip(t.chars()) {
        if a != b {
            if n > 0 {
                output.push(a);
                n -= 1;
            } else {
                output.push(b);
            }
        } else {
            output.push(a);
        }
    }

    writeln!(io::stdout(), "{}", output)?;
    Ok(())
}

