    let mut m1 = vec![0; n];
    let mut ss = x[0];
    s1[0] = x[0];
    m1[0] = 0;

    for i in 1..n {
        if i < k {
            s1[i] = s1[i - 1] + x[i];
            m1[i] = i;
            ss += x[i];
        } else {
            if ss + x[i] - x[i - k] > s1[i - 1] {
                s1[i] = ss + x[i] - x[i - k];
                m1[i] = i;
            } else {
                s1[i] = s1[i - 1];
                m1[i] = m1[i - 1];
            }
            ss = ss + x[i] - x[i - k];
        }
    }

    let mut s2 = vec![0; n];
    let mut m2 = vec![0; n];
    s2[n - 1] = x[n - 1];
    m2[n - 1] = n as i32 - 1;
    ss = x[n - 1];

    for i in (0..n - 1).rev() {
        if i >= n - k {
            s2[i] = s2[i + 1] + x[i];
            ss += x[i];
            m2[i] = i as i32;
        } else {
            if ss + x[i] - x[i + k] >= s2[i + 1] {
                s2[i] = ss + x[i] - x[i + k];
                m2[i] = i as i32;
            } else {
                s2[i] = s2[i + 1];
                m2[i] = m2[i + 1];
            }
            ss = ss + x[i] - x[i + k];
        }
    }

    let mut max = 0;
    let mut s = -1;
    for i in k - 1..n - k {
        if s1[i] + s2[i + 1] > max {
            s = i as i32;
            max = s1[i] + s2[i + 1];
        }
    }

    println!("{} {}", m1[s as usize] - k + 2, m2[(s + 1) as usize] + 1);
}

