fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    if let Some(Ok(t_str)) = lines.next() {
        if let Ok(t) = t_str.parse::<i32>() {
            for _ in 0..t {
                if let Some(Ok(line)) = lines.next() {
                    if let Ok((a, b, c)) = parse_three_integers(&line) {
                        let raz = (a - b).abs();
                        let count_of_people = raz * 2;
                        let result = if c > count_of_people || a > count_of_people || b > count_of_people || raz <= 1 {
                            -1
                        } else if c > count_of_people / 2 {
                            c - raz
                        } else {
                            c + raz
                        };
                        println!("{}", result);
                    }
                }
            }
        }
    }
}

fn parse_three_integers(s: &str) -> Result<(i32, i32, i32), std::num::ParseIntError> {
    let mut parts = s.split_whitespace();
    let a = parts.next().unwrap_or("").parse()?;
    let b = parts.next().unwrap_or("").parse()?;
    let c = parts.next().unwrap_or("").parse()?;
    Ok((a, b, c))
}

