        if let Ok(n) = n_str.parse::<usize>() {
            for _ in 0..n {
                if let Some(Ok(line)) = lines.next() {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() == 3 {
                        if let (Ok(a), Ok(b), Ok(c)) = (
                            parts[0].parse::<i64>(),
                            parts[1].parse::<i64>(),
                            parts[2].parse::<i64>(),
                        ) {
                            match (a, b, c) {
                                (a, b, c) if a == b && b == c => println!("1 1 1"),
                                (a, b, c) if a == b && b > c => println!("1 1 {}", a - c + 1),
                                (a, b, c) if a == c && a > b => println!("1 {} 1", a - b + 1),
                                (a, b, c) if c == b && b > a => println!("{} 1 1", b - a + 1),
                                (a, b, c) if a > b && a > c => println!("0 {} {}", a - b + 1, a - c + 1),
                                (a, b, c) if b > c && b > a => println!("{} 0 {}", b - a + 1, b - c + 1),
                                (a, b, c) if c > a && c > b => println!("{} {} 0", c - a + 1, c - b + 1),
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
    }
}

