fn binsearch(x: i64) -> i64 {
    let mut left: i64 = 0;
    let mut right: i64 = 2_000_000_000;
    while left < right {
        let mid = (left + right) / 2;
        if mid * mid > x {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    left - 1
}

