        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0];
    let m = first_line[1];

    let mut a: Vec<i64> = vec![0; n + 1];
    for (i, line) in lines.by_ref().take(n).enumerate() {
        a[i + 1] = line.parse().unwrap();
    }

    let mut b: Vec<Query> = Vec::with_capacity(m);
    for _ in 0..m {
        let query_line: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        b.push(Query { x: query_line[0], y: query_line[1] });
    }

    let mut sum: Vec<i64> = vec![0; n + 1];
    for i in 2..=n {
        if a[i] < a[i - 1] {
            sum[i] = sum[i - 1] + a[i - 1] - a[i];
        } else {
            sum[i] = sum[i - 1];
        }
    }

    let mut sumr: Vec<i64> = vec![0; n + 1];
    for i in (1..n).rev() {
        if a[i] < a[i + 1] {
            sumr[i] = sumr[i + 1] + a[i + 1] - a[i];
        } else {
            sumr[i] = sumr[i + 1];
        }
    }

    for query in b {
        let result = if query.x < query.y {
            sum[query.y] - sum[query.x]
        } else {
            sumr[query.y] - sumr[query.x]
        };
