    for i in 0..n {
        for j in i + 1..n {
            if a[j] < a[i] {
                a.swap(i, j);
            }
        }
    }

    if n == 1 {
        println!("23:59");
    } else {
        let mut ans = 24 * 60 + a[0] - a[n - 1] - 1;
        for i in 1..n {
            ans = ans.max(a[i] - a[i - 1] - 1);
        }
        println!("{:02}:{:02}", ans / 60, ans % 60);
    }
}

