#define K	44
#define MD	1000000007

int main() {
	static int dp[K + 1][N + 1], ch[N + 1][K + 1], ff[K + 1];
	int t, n, k, f, a;

	dp[0][0] = 1;
	for (k = 1; k <= K; k++)
		for (n = 1; n <= N; n++) {
			int m, x = 0;

			for (a = 1; (m = n - a * k) >= 0; a++)
				x = (x + dp[k - 1][m]) % MD;
			dp[k][n] = x;
		}
	for (k = 0, f = 1; k <= K; k++) {
		ff[k] = f;
		f = (long long) f * (k + 1) % MD;
	}
	ch[0][0] = 1;
	for (n = 1; n <= N; n++) {
		ch[n][0] = 1;
		for (k = 1; k <= K; k++)
			ch[n][k] = (ch[n - 1][k] + ch[n - 1][k - 1]) % MD;
	}
	scanf("%d", &t);
	while (t--) {
		int l, ans;

		scanf("%d%d", &n, &k);
		ans = 0;
		if (k <= K)
			for (l = k; l <= n; l++)
				ans = (ans + (long long) dp[k][l] * ff[k] % MD * ch[n - l + k][k]) % MD;
		printf("%d\n", ans);
	}
	return 0;
}

