#include <stdint.h>

#define min(a, b) ((a < b) ? a : b)
#define max(a, b) ((a > b) ? a : b)

uint64_t games[51] = { UINT64_C(0) };
uint64_t wins[51] = { UINT64_C(0) };

int main() {
	int n; scanf("%d", &n);
	int i, j, a, b;
	for(i = 1; i < (n * (n - 1)) / 2; i++) {
		scanf("%d %d", &a, &b);
		games[max(a, b)] |= (UINT64_C(0x1) << min(a, b));
		wins[a]++;
	}
	uint64_t mask = UINT64_C(0x2);
	for(i = 2; i < n + 1; i++) {
		if(games[i] ^ mask) {
			uint64_t flag = games[i] ^ mask;
			for(j = 1; !(flag & UINT64_C(0x2)); j++, flag >>= 1);
			if(wins[i] > wins[j]) {
				printf("%d %d\n", i, j); return 0;
			} else {
				printf("%d %d\n", j, i); return 0;
			}
		}
		mask = (mask << 1) | UINT64_C(0x2);
	}
	return 0;
}

