        rad=r/2;
    }

    else
    {
        x3=((r+dis)*x1-r*x2)/dis;
        y3=((r+dis)*y1-r*y2)/dis;

        xap=(x2+x3)/2;
        yap=(y2+y3)/2;

        rad=sqrt((x3-xap)*(x3-xap)+(y3-yap)*(y3-yap));
    }

