        let y3 = ((r + dis) * y1 - r * y2) / dis;

        let xap = (x2 + x3) / 2.0;
        let yap = (y2 + y3) / 2.0;

        let rad = ((x3 - xap).powi(2) + (y3 - yap).powi(2)).sqrt();

