        a += N;
        b += N;
        while (a < b)
        {
            if ((a & 1) == 0)
            {
                ans += f[a];
                ans %= MOD;
                a++;
            }
            if ((b & 1) == 1)
            {
                ans += f[b];
                ans %= MOD;
                b--;
            }
            a = (a-1) / 2;
            b = (b-1) / 2;
        }
        if (a == b)
        {
            ans += f[a];
            ans %= MOD;
        }
