        for a in 0..(1 << (k - 1)) {
            if x == 2 || x == 0 {
                dq[a + 1] = (dq[a + 1] + dp[a]) % MD;
            }
            if x == 4 || x == 0 {
                let a_ = if a % 2 == 0 { a + 2 } else { 2 };
                dq[a_] = (dq[a_] + dp[a]) % MD;
            }
        }
        dp.copy_from_slice(&dq);
        if x == 0 {
            sum = sum * 2 % MD;
        }
        sum = (sum + dp[1 << (k - 1)]) % MD;
    }

    println!("{}", sum);
}

