#include <math.h>

int main() {
    int t;
    scanf("%d", &t);

    for (int i = 0; i < t; ++i) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);

        int max;
        int min;
        if (a > b) {
            max = a;
            min = b;
        }
        else{
            max = b;
            min = a;
        }

        int result;
        int delta = abs(a - b);
        if (delta - 1 >= min - 1){
            if (delta == 1)
                printf("%d\n", -1);
            else if (c <= delta * 2) {
                result = c > max ? c - delta : c + delta;
                if (result > delta * 2)
                    result -= delta * 2;

                printf("%d\n", result);
            }
            else
                printf("%d\n", -1);
        }
        else
            printf("%d\n", -1);
    }

    return 0;
}

