    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let line = lines.next().unwrap().unwrap();
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let s: i64 = parts.next().unwrap().parse().unwrap();

        let mut vrs = Vec::with_capacity(n);
        let mut psum = Vec::with_capacity(n);

        let first_value: i64 = lines.next().unwrap().unwrap().parse().unwrap();
        vrs.push(first_value);
        psum.push(first_value);

        for i in 1..n {
            let value: i64 = lines.next().unwrap().unwrap().parse().unwrap();
            vrs.push(value);
            psum.push(psum[i - 1] + value);
        }

        let mut ans = 0;
        let mut lf = 0;
        let mut rt = n - 1;

        while lf < rt {
            let mid = (lf + rt + 1) / 2;
            if psum[mid] <= s {
                lf = mid;
                continue;
            }
            for i in 0..=mid {
                if psum[mid] - vrs[i] <= s {
                    ans = i + 1;
                    lf = mid;
                    break;
                }
            }
            if lf != mid {
                rt = mid - 1;
            }
        }

        println!("{}", ans);
    }
}

