int main() {
	static char aa[N][N];
	static int qq[N], dd[N];
	int n, m, i, j, d, head, cnt;

	scanf("%d%d", &n, &m);
	while (m-- > 0) {
		scanf("%d%d", &i, &j);
		i--, j--;
		aa[i][j] = aa[j][i] = 1;
	}
	if (aa[0][n - 1])
		for (i = 0; i < n; i++)
			for (j = i + 1; j < n; j++)
				aa[i][j] = aa[j][i] = 1 - aa[i][j];
	for (i = 0; i < n; i++)
		dd[i] = -1;
	head = cnt = 0;
	qq[head + cnt++] = 0, dd[0] = 0;
	while (cnt > 0) {
		i = qq[head++];
		d = dd[i];
		cnt--;
		if (i == n - 1) {
			printf("%d\n", d);
			return 0;
		}
		for (j = 0; j < n; j++)
			if (aa[i][j] && dd[j] == -1)
				qq[head + cnt++] = j, dd[j] = d + 1;
	}
	printf("-1\n");
	return 0;
