    let mut aa = vec![vec![0; n]; n];
    for _ in 0..m {
        let line: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let (i, j) = (line[0] - 1, line[1] - 1);
        aa[i][j] = 1;
        aa[j][i] = 1;
    }

    if aa[0][n - 1] == 1 {
        for i in 0..n {
            for j in i + 1..n {
                aa[i][j] = 1 - aa[i][j];
                aa[j][i] = aa[i][j];
            }
        }
    }

    let mut dd = vec![-1; n];
    let mut qq = Vec::with_capacity(n);
    let mut head = 0;
    let mut cnt = 0;

    qq.push(0);
    dd[0] = 0;
    cnt += 1;

    while cnt > 0 {
        let i = qq[head];
        let d = dd[i];
        head += 1;
        cnt -= 1;

        if i == n - 1 {
            println!("{}", d);
            return;
        }

        for j in 0..n {
            if aa[i][j] == 1 && dd[j] == -1 {
                qq.push(j);
                dd[j] = d + 1;
                cnt += 1;
            }
        }
    }

    println!("-1");
}

