	for (i = 0, j = 0, j_ = 0; i <= k; i++) {
		b = aa[i] + ta;
		while (j < m && bb[j] < b)
			j++;
		j_ = j + k - i;
		if (j_ >= m) {
			printf("-1\n");
			return 0;
		}
		if (ans < (c = bb[j_] + tb))
			ans = c;
	}
	printf("%d\n", ans);
	return 0;
