                    aa[k][j] = 0;
                }
                for l in 0..m {
                    aa[i][l] = 0;
                }
            }
        }
    }

    for (i, row) in bb.iter().enumerate() {
        for (j, &val) in row.iter().enumerate() {
            let mut x = 0;
            for k in 0..n {
                x |= aa[k][j];
            }
            for l in 0..m {
                x |= aa[i][l];
            }
            if x != val {
